            {
              "type": "text",
              "content": "A small recurring expense can matter, but a major structural expense may have a much larger effect on cash flow. Focus your effort where it can make a meaningful difference."
            },
            {
              "type": "example",
              "title": "Small versus large changes",
              "content": "Saving $10 once is useful, but reducing a recurring monthly expense by $100 creates a larger ongoing improvement."
            },
            {
              "type": "heading",
              "content": "Look for income opportunities too"
            },
            {
              "type": "text",
              "content": "Cash-flow improvement does not always have to come from spending cuts. Depending on your situation, increasing income may also be part of the solution."
            },
            {
              "type": "heading",
              "content": "Use a simple cash-flow review"
            },
            {
              "type": "text",
              "content": "At the end of a period, compare total money in, total money out, the timing of major transactions, and the amount left for future priorities."
            },
            {
              "type": "interactive",
              "title": "Your cash-flow check",
              "content": "Ask: How much came in? How much went out? When did the largest payments happen? Did the timing create pressure? What amount remained?"
            },
            {
              "type": "heading",
              "content": "Cash flow and financial breathing room"
            },
            {
              "type": "text",
              "content": "A positive cash-flow pattern can create breathing room. That breathing room can support savings, debt reduction, planned spending, and preparation for future expenses."
            },
            {
              "type": "heading",
              "content": "The goal is not a perfect number"
            },
            {
              "type": "text",
              "content": "There is no universal cash-flow amount that guarantees financial success. The goal is to understand your own numbers and create enough flexibility to handle your responsibilities and priorities."
            },
            {
              "type": "heading",
              "content": "Build the habit of checking before spending"
            },
            {
              "type": "text",
              "content": "Before making a significant purchase, consider what other payments are coming soon. A purchase that looks affordable today may create pressure if a major bill is due tomorrow."
            },
            {
              "type": "example",
              "title": "The upcoming bill",
              "content": "You have $600 available and want to spend $250. If a $500 essential bill is due before your next income arrives, the purchase is not comfortably affordable even though your current balance is $600."
            },
            {
              "type": "heading",
              "content": "Think forward, not only backward"
            },
            {
              "type": "text",
              "content": "Reviewing past transactions is useful, but good cash-flow management also asks what money is expected to come in and what money is expected to go out next."
            },
            {
              "type": "heading",
              "content": "Cash flow is a decision-making tool"
            },
            {
              "type": "text",
              "content": "Once you understand your cash flow, you can make better decisions about spending, saving, debt, and timing."
            },
            {
              "type": "summary",
              "content": "Cash flow shows the relationship between money coming in and money going out. Track both amount and timing, account for upcoming commitments, identify whether problems come from income, expenses, or timing, and use the information to create more breathing room."
            },
            {
              "type": "callout",
              "title": "Remember",
              "content": "A bank balance tells you what you have right now. Cash flow helps you understand what is happening and what may happen next."
            }
